def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]!=3 and grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]==3:
                centers.append((r,c,grid[r][c]))
    # Rays stop at the arms of a different cross. Keep each cross's own arms intact.
    for r,c,color in centers:
        for dc in (-1,1):
            j=c+dc
            distance=1
            while 0<=j<w:
                if grid[r][j]==3:
                    if distance>1: break
                else:
                    out[r][j]=color
                j+=dc; distance+=1
    for r,c,color in centers:
        for dr in (-1,1):
            i=r+dr
            distance=1
            while 0<=i<h:
                if grid[i][c]==3:
                    if distance>1: break
                else:
                    out[i][c]=color
                i+=dr; distance+=1
    return out
